```java
import java.util.*;

public class Main {
    static final int N=10, M=1000007, K=200, p=1000000007;
    static int n;
    static int[] s = new int[M];
    static int[] wf = new int[K];
    static int[][] q = new int[N+1][K];
    static int[][] f = new int[N+1][N+1];
    static int[][] ans = new int[N+1][M];
    static long[][] wq = new long[N+1][M];
    static Map<Long,Integer>[] rt = new HashMap[N+1];
    static long op = 0L; // zero bitset

    static int readInt() {
        int num = 0;
        char g;
        try {
            g = (char) System.in.read();
            while (g < '0' || g > '9') g = (char) System.in.read();
            while (g >= '0' && g <= '9') {
                num = (num << 1) + (num << 3) + (g - '0');
                g = (char) System.in.read();
            }
        } catch (Exception e) {}
        return num;
    }

    static long pow(long u, int v) {
        long ans = 1;
        while (v > 0) {
            if ((v & 1) == 1) ans = (ans * u) % p;
            u = (u * u) % p;
            v >>= 1;
        }
        return ans;
    }

    static void find(int u) {
        q[u][0] = 0;
        int os = 0, of = 0;
        for (int i = 0; i < (1 << n); i++) {
            if (s[i] == u) {
                q[u][++q[u][0]] = i;
                wf[i] = ++os;
            }
        }
        for (int i = 1; i <= e[u - 1]; i++) {
            if (ans[u - 1][i] == 0) continue;
            for (int h = 1; h < (1 << n); h++) {
                long opq = 1;
                for (int c = 0; c < n; c++) {
                    if ((h & (1 << c)) != 0) {
                        opq = (opq * f[u][c + 1]) % p;
                    } else {
                        opq = (opq * (1 - f[u][c + 1] + p)) % p;
                    }
                }
                long c = wq[u - 1][i];
                long hc = op;
                boolean tg = false;
                for (int x = 1; x <= q[u - 1][0]; x++) {
                    if ((c & (1L << (x - 1))) != 0) { // c[x]==1
                        for (int t = 0; t < n; t++) {
                            if (((h & (1 << t)) != 0) && ((q[u - 1][x] & (1 << t)) == 0)) {
                                int state = q[u - 1][x] | (1 << t);
                                hc |= (1L << (wf[state] - 1));
                                tg = true;
                            }
                        }
                    }
                }
                if (!tg) continue;
                int pos;
                if (!rt[u].containsKey(hc)) {
                    rt[u].put(hc, ++of);
                    e[u]++;
                    wq[u][e[u]] = hc;
                }
                pos = rt[u].get(hc);
                ans[u][pos] = (int)((ans[u][pos] + opq * ans[u - 1][i]) % p);
            }
        }
    }

    static int[] e = new int[N+1]; // need to be class-level for find to access

    public static void main(String[] args) {
        for (int i = 0; i <= N; i++) {
            rt[i] = new HashMap<>();
        }
        n = readInt();
        for (int i = 0; i <= (1 << n); i++) {
            s[i] = Integer.bitCount(i);
        }
        long inv100 = pow(100, p - 2);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                f[i][j] = (int)((long)readInt() * inv100 % p);
            }
        }
        q[0][0] = 1;
        e[0] = 1;
        ans[0][1] = 1;
        wq[0][1] = 1L; // bit 1 set
        for (int i = 1; i <= n; i++) {
            find(i);
        }
        System.out.println(ans[n][1]);
    }
}
